import{_ as l,o as a,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph User + Dev Monthly 2024-01-18","description":"","frontmatter":{"title":"Ceph User + Dev Monthly 2024-01-18","date":"2024-01-18T00:00:00.000Z","updated":"2024-01-23T00:00:00.000Z","tags":["Ceph","分布式存储","对象存储","磁带存储","功能请求"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_User_+_Dev_Monthly_2024-01-18.md","filePath":"posts/2024/Ceph_User_+_Dev_Monthly_2024-01-18.md","lastUpdated":1780460162000}'),o={name:"posts/2024/Ceph_User_+_Dev_Monthly_2024-01-18.md"};function r(s,e,n,h,p,_){return a(),t("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><p>本次Ceph用户开发会议中，国家太阳能天文台的SEF操作员Joel Davido提出了使用磁带作为对象存储类功能请求。Joel详细介绍了该请求的背景、优势、潜在用途以及当前的技术选项，并讨论了可能的实施方案和挑战。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>背景介绍</strong>：</p><ul><li>Joel介绍了DEIS项目，特别是Daniel K. Inouye太阳望远镜的数据收集、存储和归档过程。</li></ul></li><li><p><strong>功能请求</strong>：</p><ul><li>在Ceph中添加一个由磁带支持的服务，类似于AWS Glacier，以实现长期数据存储和降低成本。</li></ul></li><li><p><strong>优势与用途</strong>：</p><ul><li>磁带存储可以减少存储成本、空间利用、电力消耗和冷却负荷，主要用于长期存档和防止勒索软件攻击。</li></ul></li><li><p><strong>当前技术选项</strong>：</p><ul><li>讨论了第三方应用程序和方法，如Spectra Logic的Black Pearl、StoreCycle和Nodiam的产品，以及S3 API拦截等。</li></ul></li><li><p><strong>期望的功能</strong>：</p><ul><li>需要原生集成、透明媒体转换、避免单点故障、程序化管理S3请求等功能。</li></ul></li><li><p><strong>实施方案讨论</strong>：</p><ul><li>提出了使用S3生命周期管理、Glacier API等方法，以及可能的实施步骤和挑战。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>会议决定创建一个跟踪器票证，以跟踪该功能的进展和未来开发。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>创建一个跟踪器票证，详细记录功能请求和相关讨论。</li><li>分解票证为更小的任务，以便逐步实现。</li><li>继续讨论和探索实施细节，特别是关于S3生命周期管理和Glacier API的集成。</li></ul><h4 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h4><ul><li>会议记录将被上传到档案，并与跟踪器票证链接，以便后续参考和跟进。</li></ul><p>本次会议为Ceph社区提供了一个讨论和探索磁带存储在对象存储中应用的平台，有助于推动相关技术的进步和应用。</p>',12)])])}const c=l(o,[["render",r]]);export{d as __pageData,c as default};
